Q: Attempted to finish an input event but the input event receiver has already been disposed error A: <p>The problem is in the following section:</p>

<pre><code>AlertDialog.Builder Alert = new AlertDialog.Builder(this);
Alert.setMessage("Correct!")
                    .create();
Alert.show();
Intent i = new Intent(MainActivity.this, Main2Activity.class);
startActivity(i);
</code></pre>

<p>You are getting the error because you are trying to show an alert right before starting a new activity. Now, the 'receiver' for the dialog is the current activity and as soon as you start new activity that is switched. To tackle this problem you can try something like this:</p>

<pre><code>Alert.setPositiveButton("OK", new DialogInterface.OnClickListener() {
    public void onClick(DialogInterface dialog, int id) {
         Intent i = new Intent(MainActivity.this, Main2Activity.class);
         startActivity(i);
    } 
</code></pre>

<p>TL;DR: Can't show an alert right before starting a new activity.</p>

Q: How can I implement Java-like enums in Go? A: <p>Usage demonstrates:</p>
<ol>
<li><p>singleton identity (<code>==</code>)</p>
</li>
<li><p>natural <code>switch</code></p>
</li>
<li><p>efficient lookup</p>
</li>
<li><p>per-constant state</p>
</li>
</ol>
<pre class="lang-golang prettyprint-override"><code>// Identity comparison (compares underlying shared reference)
if notification.Type == notificationType.Progress {
    ...
}

// Switch
switch notification.Type {
case notificationType.Message:
    ...
case notificationType.Progress:
    ...
default:
    panic(&quot;unknown notification type&quot;)  
}

// Name and ordinal
fmt.Println(notification.Type.Name())    // &quot;Progress&quot;
fmt.Println(notification.Type.Ordinal()) // 1

// Lookup by name
t := notificationType.Enum.ValueOf(&quot;Progress&quot;)

// Lookup by ordinal
t := notificationType.Enum.ValueOfOrdinal(1)

// Enumerate all values
for _, t := range notificationType.Enum.Values() {
    fmt.Println(t.Name())
}

// Additional state
fmt.Println(t.DisplayName())
</code></pre>
<p><em><strong>NotificationType</strong></em> definition</p>
<pre class="lang-golang prettyprint-override"><code>package notificationType

var Message = newNotificationType(&quot;Message&quot;, &quot;Message display name&quot;)
var Progress = newNotificationType(&quot;Progress&quot;, &quot;Progress display name&quot;)

var Enum = enum.NewEnum(
    Message,
    Progress,
)

type NotificationType struct {
    enum.EnumValue[NotificationType]
    displayName string
}

func newNotificationType(name, displayName string) NotificationType {
    return NotificationType{
        EnumValue:   *enum.NewEnumValue[NotificationType](name),
        displayName: displayName,
    }
}

func (this *NotificationType) MarshalJSON() ([]byte, error) {
    return json.Marshal(this.Name())
}

func (this *NotificationType) UnmarshalJSON(data []byte) error {
    var name string
    assert.NoError(json.Unmarshal(data, &amp;name), &quot;Cannot unmarshal NotificationType&quot;)
    *this = Enum.ValueOf(name)
    return nil
}
</code></pre>
<p><em><strong>Enum.go</strong></em></p>
<pre class="lang-golang prettyprint-override"><code>package enum

type value[T any] interface {
    Name() string
    setOrdinal(int)
    setDescriptor(*Enum[T])
}

type Enum[T any] struct {
    byName    map[string]T
    byOrdinal []T
}

func NewEnum[T value[T]](values ...T) *Enum[T] {
    d := &amp;Enum[T]{
        byName:    make(map[string]T, len(values)),
        byOrdinal: make([]T, len(values)),
    }
    for i, value := range values {
        value.setOrdinal(i)
        value.setDescriptor(d)
        if _, exists := d.byName[value.Name()]; exists {
            panic(&quot;Duplicate enum constant: &quot; + value.Name())
        }
        d.byName[value.Name()] = value
        d.byOrdinal[i] = value
    }
    return d
}

func (this *Enum[T]) ValueOf(name string) T {
    v, ok := this.byName[name]
    assert.True(ok, &quot;No enum constant %T.%s&quot;, this, name)
    return v
}

func (this *Enum[T]) ValueOfOrdinal(ordinal int) T {
    assert.True(ordinal &gt;= 0 &amp;&amp; ordinal &lt; len(this.byOrdinal), &quot;Invalid ordinal %T: %d&quot;, this, ordinal)
    return this.byOrdinal[ordinal]
}

func (this *Enum[T]) Values() []T {
    return append([]T(nil), this.byOrdinal...)
}
</code></pre>
<p><em><strong>EnumValue.go</strong></em></p>
<pre class="lang-golang prettyprint-override"><code>package enum

func ValueOf[T any](d *Enum[T], name string) T {
    return d.ValueOf(name)
}

func ValueOfOrdinal[T any](d *Enum[T], ordinal int) T {
    return d.ValueOfOrdinal(ordinal)
}

func ValuesOf[T any](d *Enum[T]) []T {
    return d.Values()
}

type enumValue[T any] struct {
    enum    *Enum[T]
    name    string
    ordinal int
}

type EnumValue[T any] struct {
    value *enumValue[T]
}

func NewEnumValue[T any](name string) *EnumValue[T] {
    return &amp;EnumValue[T]{value: &amp;enumValue[T]{name: name, ordinal: -1}}
}

func (this EnumValue[T]) Name() string {
    return this.value.name
}

func (this EnumValue[T]) Ordinal() int {
    return this.value.ordinal
}

func (this EnumValue[T]) Enum() *Enum[T] {
    return this.value.enum
}

func (this EnumValue[T]) String() string {
    return this.value.name
}

func (this EnumValue[T]) setOrdinal(ordinal int) {
    this.value.ordinal = ordinal
}

func (this EnumValue[T]) setDescriptor(descriptor *Enum[T]) {
    this.value.enum = descriptor
}
</code></pre>

Q: Flutter web deploy to production: Failed to load app from service worker A: <p>Flutter is phasing out the Service Worker that allows your app to cache locally. The way to fix this issue is to clear the Service Worker from the file: web/flutter_bootstrap.js</p>
<p>There will be a section that looks something like the code below. Just remove the <code>serviceWorkerSettigns: {}</code> content.</p>
<pre><code>_flutter.loader.load({
  serviceWorkerSettings: {
    serviceWorkerVersion: {{flutter_service_worker_version}},
  },
});
</code></pre>

Q: Why does Next.js dynamic import fail with &quot;window is not defined&quot; during server-side rendering? A: <p>Node.js doesn't have a <code>window</code> object like the browser does.   <a href="https://bun.com/" rel="nofollow noreferrer">Bun</a> does, but you're probably deploying to Vercel, so that won't help you.</p>
<p>You'll need to guard your code to make sure that when it's running SSR you don't call that package, and if you need a value from that package on the server render, you'll need to instead pass over a default value.  For example, if you need to have the window's width you would need to pass over a default like 1080, or 767.</p>
<p>I believe the thing you're looking for in the Next eco system is: <a href="https://nextjs.org/docs/pages/guides/lazy-loading#nextdynamic-1" rel="nofollow noreferrer">'next/dynamic'</a></p>
<pre><code>import dynamic from 'next/dynamic'

const DynamicHeader = dynamic(() =&gt; import('../components/header'), {
  loading: () =&gt; &lt;p&gt;Loading...&lt;/p&gt;,
})

export default function Home() {
  return &lt;DynamicHeader /&gt;
}
</code></pre>
